    refresh() {
        this.setState({ dataSource: generateGroupData(generateNumber(2, 6), 'root') });
    }
    render() {
        const { disabled, search, clearable, size, separator, dataSource } = this.state;
        const props = {
            disabled,
            search,
            clearable,
            size,
            dataSource
        };
        switch (separator) {
            case '-':
