const generateItems = (count, prefix, need) => {
    return new Array(count).fill(null).map((v, i) => {
        const key = `${prefix}-${i}-item`;
        let subItems = [];
        if (need && i === 5) {
            subItems = generateItems(6, key);
        }
        const item = {
            key: key,
            title: key
        };
        if (subItems.length) {
            item.children = subItems;
        }
        return item;
    });
};

