            showPagination: true,
            zebraCrossing: false,
            columnPlaceholder: false,
            rowSelectionSelectedTip: true,
            tableLayout: 'default',
            scroll: {
                x: false,
                y: false
            }
        };
    }
    render() {
        const {
            dataLength,
            columnLength,
            rowSelection,
            searchInput,
            columnConfigButtom,
            fixedFirstColumn,
            fixedLastColumn,
            hasError,
            removeLastButOneColumnWidth,
            showHeader,
            showPagination,
            scroll,
            zebraCrossing,
            columnPlaceholder,
            tableLayout,
            rowSelectionSelectedTip
        } = this.state;
        let dataSource = [];
