class Demo extends React.Component {
    constructor(props) {
        super(props);
        this.columns = [
            {
                title: 'name',
                dataIndex: 'name',
                key: 'name',
                width: 100,
                filter: {
                    options: [1, 2, 3, 4]
                },
                order: true
            },
            {
                title: 'desc',
                dataIndex: 'desc',
                key: 'desc',
                width: 200,
                filter: {
                    options: [1, 2, 3, 4],
                    multiple: true
                },
                order: true
            },
            {
                title: 'Operations',
                dataIndex: '',
                key: 'operation',
                render: (text, record) => (
                    <a onClick={e => this.handleRemove(record.key, e)} href="#">
                        Remove
                    </a>
                )
            }
        ];
        let data = [];
        data.length = 100;
        data.fill({});
        data = data.map((d, i) => ({
            key: i + '',
            name: `name-${i}`,
            desc: `desc-${i}`
        }));
        this.state = {
            data,
            selectedRowKeys: []
        };
    }
    handleRemove(key, e) {
        console.log('Remove', key);
        e.preventDefault();
        const data = this.state.data.filter(item => item.key !== key);
        this.setState({ data });
        this.setState({
            selectedRowKeys: this.state.selectedRowKeys.filter(_key => _key !== key)
        });
    }
    handleAdd() {
        const data = [...this.state.data];
        const key = Date.now();
        data.unshift({
            name: `name-${key}`,
            desc: `desc-${key}`,
            key: Date.now()
        });
        this.setState({ data });
    }
    handleRemoveSelected() {
        const { selectedRowKeys } = this.state;
        const data = this.state.data.filter(record => _.findIndex(selectedRowKeys, key => key === '' + record.key) < 0);
        this.setState({ data });
        this.setState({
            selectedRowKeys: []
        });
    }
    render() {
        const { selectedRowKeys } = this.state;
        return (
            <Table
                columns={this.columns}
                dataSource={this.state.data}
                rowSelection={{
                    selectedRowKeys,
                    onChange: (selectedRowKeys, selectedRows) => {
                        console.log(selectedRowKeys, selectedRows);
                        this.setState({ selectedRowKeys });
                    }
                }}
                title={() => {
                    return (
                        <Box container justifyContent="space-between">
                            <Combine>
                                <Button onClick={() => this.handleAdd()} styleType="primary">
                                    新增
                                </Button>
                                <Button
                                    disabled={!selectedRowKeys || !selectedRowKeys.length}
                                    onClick={() => this.handleRemoveSelected()}
                                >
                                    删除
                                </Button>
                            </Combine>
                            <Combine>
                                <Table.SearchInput />
                                <Table.ColumnConfigButton />
                            </Combine>
                        </Box>
                    );
                }}
                defaultColumnConfig={{
                    name1: {
                        disabled: true,
                        hidden: true
                    }
                }}
                onColumnConfigChange={console.log}
                contextMenu={(record, hide) => (
                    <Menu selectable={false}>
                        <Menu.Item
                            onClick={e => {
                                this.handleRemove(record.key, e);
                                hide();
                            }}
                        >
                            Remove
                        </Menu.Item>
                        <Menu.Item
                            onClick={() => {
                                console.log(record);
                                hide();
                            }}
                        >
                            Log
                        </Menu.Item>
                    </Menu>
                )}
            />
        );
    }
}

class Demo extends React.Component {
    render() {
        const dataSource = new Array(100).fill(null).map((v, i) => ({
            key: i,
            index: `index-${i}`
        }));
        const columns = [
            {
                /**
                 * @type {node}
                 * 表头展示内容，也是自定义表头弹窗中的展示内容
                 */
                title: `title`,
                /**
                 * @type {function}
                 * @param title - 上面的title
                 * 自定义表头展示内容，使用这个可以不影响在自定义弹窗中的展示
                 */
                renderTitle: title => (
                    <span>
                        <Icon type="circle" />
                        <span>{title}</span>
                        <Icon type="square" />
                    </span>
                ),
                /**
                 * @type {string}
                 * column的key，必传，用作性能优化和标识，不能重复
                 */
                key: `title`,
                /**
                 * @type {number}
                 * 固定列宽，表格固定宽度时会按照权重比例分割
                 */
                width: 200,
                /**
                 * @type {object}
                 * 筛选信息
                 * @property {array} options - 筛选选项
                 * @property {boolean} multiple - 是否为多选
                 * @property {string|string[]} defaultValue - 非受控默认筛选值
                 * @property {string|string[]} value - 受控筛选值
                 * @property {node|object} extra - 嵌入额外内容，具体使用可参考 Select.extra
                 * @property {function} handleFilter - 自定义筛选函数
                 *      @param value - 根据dataIndex计算出来的值
                 *      @param record - 列表的数据
                 *      @param filterValue - 筛选的值
                 */
                filter: {
                    options: [1, 2, 3, 4]
                },
                /**
                 * @type {boolean | object}
                 * 是否支持排序，可传入handleOrder进行自定义排序逻辑
                 */
                order: true,
                /**
                 * @type {string}
                 * 指定数据key，默认展示为record[dataIndex]
                 */
                dataIndex: 'index',
                /**
                 * @type {function}
                 * @param value - 根据dataIndex计算出来的值，未传入dataIndex时为record
                 * @param record - 列表的数据
                 * @param index - 数据在该页的index，请勿使用该index，因为这个index为不可信数据，同一条数据在分页、筛选等变动时index不一致
                 * 自定义渲染内容
                 */
                render: value => {
                    return <span>content {value}</span>;
                }
            }
        ];
        return (
            <div>
                <div className="demo-wrap">
                    <Table dataSource={dataSource} columns={columns} />
                </div>
            </div>
        );
    }
}

