        this.state = {
            dataSource: [],
            seleted: [],
            pagination: {
                total: 0
            }
        };
    }
    componentDidMount() {
        this.fetch({
            current: 1,
            pageSize: 10
        });
    }

    fetch(params) {
        console.log('params: ', params);
        const { current, pageSize } = params;
        this.setState({
            loading: true,
            pagination: {
                ...this.state.pagination,
                current,
                pageSize
            }
        });
        return new Promise(resolve => {
            const data = new Array(pageSize).fill(null).map((v, i) => ({
                index: i + (current - 1) * pageSize,
                children: [1, 2].map((d, j) => ({
                    index: i + (current - 1) * pageSize + '-' + j
                }))
            }));
            setTimeout(() => {
                resolve({
                    dataSource: data,
                    total: 101
                });
            }, 1000);
        }).then(result => {
            this.setState({
                loading: false,
                dataSource: result.dataSource,
                pagination: {
                    ...this.state.pagination,
                    total: result.total
                }
            });
        });
    }
    handlePaginationChange(current, pageSize) {
        this.fetch({
            current,
            pageSize
        });
    }
    render() {
        const { dataSource, pagination, loading, seleted } = this.state;
        const columns = new Array(5).fill(null).map((v, i) => ({
            title: `title-${i}`,
