            dataSource: dataSourceAfterSearch,
            count,
            openKeys: Object.keys(finalExpandedKeyMap)
        };
    }, []);
    return (
        <>
            <DemoWrap>
                <Tree
                    dataSource={_dataSource}
                    multiple
                    onChange={console.log}
                    collapseProps={{
                        onChange: console.log
                    }}
                    search
                />
            </DemoWrap>
            <DemoWrap>
                <h2>自定义模拟后端搜索</h2>
                <Tree
                    dataSource={_dataSource}
                    multiple
                    onChange={console.log}
                    collapseProps={{
                        onChange: console.log
                    }}
                    search={{ handleSearch }}
                />
            </DemoWrap>
            <DemoWrap>
                <h2>搜索+全选等，搜索结果页面后的全选、反选、取消选择针对的是当前搜索结果</h2>
                <Box container spacing="md" direction="column">
                    <Combine>
                        <Button styleType="primary" onClick={() => ref.current.selectAll()}>
                            全选
                        </Button>
                        <Button onClick={() => ref.current.inverse()}>反选</Button>
                        <Button onClick={() => ref.current.unSelectAll()}>取消选择</Button>
                    </Combine>
                    <Tree
                        dataSource={_dataSource}
                        multiple
                        onChange={console.log}
                        collapseProps={{
                            onChange: console.log
                        }}
                        search
                        ref={ref}
                    />
                </Box>
            </DemoWrap>
        </>
    );
};

const generateItems = (count, prefix, depth) => {
    return new Array(count).fill(null).map((v, i) => {
        const key = `${prefix}-${i}-item`;
        let subItems = [];
        if (depth) {
            subItems = generateItems(6, key, depth - 1);
        }
        const item = {
            key: key,
            title: key
        };
        if (subItems.length) {
            item.children = subItems;
        }
        return item;
    });
};

const generateGroupData = (depth, prefix) => {
    const itemCount = 6;
    const menuItems = generateItems(itemCount, prefix, depth);
    return menuItems;
};

const initDataSource = generateGroupData(5, 'root');

const Demo = () => {
    const [dataSource, setDataSource] = React.useState(initDataSource);
    const refresh = React.useCallback(() => {
        setDataSource(generateGroupData(5, 'root'));
    }, []);
    const ref = React.useRef();
    return (
        <>
            <Combine>
                <Button onClick={refresh}>Refresh</Button>
                <h2>总计 6**6 = 46656 条数据</h2>
            </Combine>
            <Tree dataSource={dataSource} multiple onChange={console.log} ref={ref} />
        </>
    );
};

components.doc:
### 说明

-   这是 Tree - 树组件
-   与程序树概念不同，按照目前的交互这里的树父节点、子节点有着本质的区别，选中只包括子节点，父节点只做展示，故数据结构中的称谓也有所差异

### 数据结构

#### Key

```ts {"static": true}
// 值需为 string
type Key = string;
```

#### LoadData

```ts {"static": true}
interface LoadData {
    (key: Key): Promise<void>;
}
```

#### TreeData

```ts {"static": true}
interface TreeData {
    // 唯一键，所有值的字符串不得重复，会用作 key 和选中判定，如果为其它值会转为 string 再应用
    key: Key;
    // 选项标题内容
    title: ReactNode;
    // 子数据，存在即为父节点，不存在即为叶子结点，与程序树有差异，原因详见说明
    children?: TreeData[];
    // 是否禁用，父节点禁用会禁用所有子孙节点
    disabled?: boolean;
    // 是否强制为父节点
    isParent?: boolean;
}
```

### 交互逻辑

1. 全选、反选、取消选择 等内置方法不会影响禁用项目的勾选状态
2. 全选状态的展示与禁用项目无关
3. 存在禁用选中项时会展示部分选中

### 演示

#### 功能演示

```js {"codepath": "tree.jsx"}
```

#### method - 内置方法

注意全选和反选只有多选模式下生效

```js {"codepath": "method.jsx"}
```

#### controlled / uncontrolled - 受控 / 非受控

```js {"codepath": "controlled.jsx"}
```

#### loadData - 异步加载数据

1. 异步加载数据需要在待加载的父级数据中添加 isParent，来告知组件展示展开按钮，通过 loadData 来加载数据后需要更新 DataSource
2. 由于 Tree 为 Memo Component，更新时需要更新引用
3. 异步加载需注意无法使用多选场景，多选时数据未加载无法获取选中数据

```js {"codepath": "loadData.jsx"}
```

#### search - 搜索

使用 Promise search.handleSearch，来控制搜索 loading 状态，后触发的搜索搜索结果会覆盖之前的，内部已处理

```js {"codepath": "search.jsx"}
```

#### 大数据性能测试

```js {"codepath": "bigData.jsx"}
```

